import Foundation
final class EvaartaRuntimeTransportBridge{private let manager:EvaartaTransportManager;private let queue:EvaartaStoreForwardQueue;init(manager:EvaartaTransportManager,queue:EvaartaStoreForwardQueue){self.manager=manager;self.queue=queue};func send(_ e:EvaartaEnvelope) async->EvaartaDeliveryReceipt{let r=await manager.send(e);switch r{case .success:return EvaartaDeliveryReceipt(messageId:e.messageId,recipient:e.destination,status:"accepted",transport:e.type,reason:nil);case .failure(let err):queue.enqueue(e);return EvaartaDeliveryReceipt(messageId:e.messageId,recipient:e.destination,status:"queued",transport:e.type,reason:err.localizedDescription)}}}
